/* @autogenerated */
package net.civeira.phylax.feature.oauth.par.infrastructure.driven;

import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.fasterxml.jackson.databind.ObjectMapper;

import net.civeira.phylax.feature.oauth.par.domain.ParRequest;
import net.civeira.phylax.testing.sql.H2Database;

/** The pushed authorization requests (RFC 9126) stored with the production sql on h2. */
class ParRequestSqlAdapterUnitTest {
  private ParRequestSqlAdapter adapter;

  @BeforeEach
  void setUp() {
    adapter = new ParRequestSqlAdapter(new H2Database().dataSource(),
        new ObjectMapper().findAndRegisterModules());
  }

  @Test
  @DisplayName("A pushed request is stored and read back on its tenant")
  void stored_and_found() {
    ParRequest request = ParRequest.create("acme", "web",
        Map.of("redirect_uri", "https://app/cb", "scope", "openid"));
    adapter.store(request);

    ParRequest found = adapter.findByUri(request.getRequestUri(), "acme").orElseThrow();
    Assertions.assertEquals("web", found.getClientId());
    Assertions.assertEquals(request.getParams(), found.getParams());
    Assertions.assertFalse(found.isUsed());
    Assertions.assertFalse(found.isExpired());
    Assertions.assertTrue(adapter.findByUri(request.getRequestUri(), "other").isEmpty(),
        "A request uri is bound to its tenant");
    Assertions.assertTrue(adapter.findByUri("urn:missing", "acme").isEmpty());
  }

  @Test
  @DisplayName("A pushed request is consumed only once and only on its tenant")
  void consume_once() {
    ParRequest request = ParRequest.create("acme", "web", Map.of("scope", "openid"));
    adapter.store(request);
    OffsetDateTime until = OffsetDateTime.now(ZoneOffset.UTC).plusSeconds(30);

    Assertions.assertFalse(adapter.consume(request.getRequestUri(), "other", until));
    Assertions.assertTrue(adapter.consume(request.getRequestUri(), "acme", until));
    Assertions.assertFalse(adapter.consume(request.getRequestUri(), "acme", until),
        "A request uri can not be used twice");
    Assertions
        .assertTrue(adapter.findByUri(request.getRequestUri(), "acme").orElseThrow().isUsed());
  }
}
